"""Mode-SFT baseline with policy rollouts generated by remote persistent vLLM.

For each prompt, the current policy generates 16 responses. If the extracted
answers have a unique non-unanimous mode, SFT is applied only to responses that
match that modal pseudo-label. No adaptation labels are used.
"""

from __future__ import annotations

import argparse
import atexit
import os
import random
import shutil
import tempfile
import time
from pathlib import Path

import torch

import common as C
import esrl_core as core
from remote_vllm_engine import adapter_sync_parent
from train_es_direct import (
    adapter_scale,
    create_initial_peft_adapter,
    rpc_one,
    validate_adapter,
    vllm_version_check,
)
from vllm_utils import request_to_sequence


def parse_args():
    parser = argparse.ArgumentParser()
    parser.add_argument("--model", default="Qwen/Qwen3-4B-Base")
    parser.add_argument(
        "--dataset", required=True, choices=("math500", "mmlu", "medqa")
    )
    parser.add_argument("--out", required=True)
    parser.add_argument("--train-size", type=int, required=True)
    parser.add_argument("--eval-size", type=int, required=True)
    parser.add_argument("--epochs", type=int, required=True)
    parser.add_argument("--population", type=int, default=16)
    parser.add_argument("--temp", type=float, default=0.8)
    parser.add_argument("--max-new", type=int, default=8196)
    parser.add_argument("--p-high", type=float, default=0.95)
    parser.add_argument("--lora-r", type=int, default=16)
    parser.add_argument("--lr", type=float, default=5e-5)
    parser.add_argument("--snap-every", type=int, default=500)
    parser.add_argument("--init-adapter", default=None)
    parser.add_argument("--start-visit", type=int, default=0)
    parser.add_argument("--max-visits", type=int, default=None)
    parser.add_argument("--permute-choices", action="store_true")
    parser.add_argument(
        "--dtype", default="bfloat16", choices=("float16", "bfloat16")
    )
    parser.add_argument("--seed", type=int, default=0)
    parser.add_argument("--data-seed", type=int, default=None)
    parser.add_argument("--max-model-len", type=int, default=12292)
    parser.add_argument("--max-num-seqs", type=int, default=16)
    parser.add_argument("--gpu-memory-utilization", type=float, default=0.40)
    parser.add_argument("--enforce-eager", action="store_true")
    args = parser.parse_args()

    if args.population < 2:
        parser.error("--population must be at least 2")
    if args.max_num_seqs < args.population:
        parser.error("--max-num-seqs must be at least --population")
    if args.max_new <= 0 or args.max_model_len <= args.max_new:
        parser.error("--max-model-len must exceed --max-new")
    if not 0.0 < args.gpu_memory_utilization < 1.0:
        parser.error("--gpu-memory-utilization must be between 0 and 1")
    if args.seed < 0 or (args.data_seed is not None and args.data_seed < 0):
        parser.error("--seed and --data-seed must be non-negative")
    if args.max_visits is not None and args.max_visits <= args.start_visit:
        parser.error("--max-visits must be greater than --start-visit")
    return args


def _rollout_prompts(item, population, visit, permute, tokenizer, instruct):
    if not permute:
        return [item] * population, [None] * population
    rng = random.Random(1_000_003 * visit + 17)
    built = [
        C.build_mmlu_rollout_prompt(item, tokenizer, instruct, rng)
        for _ in range(population)
    ]
    return [value[0] for value in built], [value[1] for value in built]


def main():
    args = parse_args()
    data_seed = args.seed if args.data_seed is None else args.data_seed
    os.environ["VLLM_USE_V1"] = "1"
    os.environ.setdefault("VLLM_WORKER_MULTIPROC_METHOD", "spawn")
    os.environ.setdefault("TOKENIZERS_PARALLELISM", "false")
    version = vllm_version_check()

    from transformers import AutoTokenizer
    from vllm import SamplingParams
    from vllm.lora.request import LoRARequest

    if os.environ.get("VLLM_REMOTE_HOST"):
        from remote_vllm_engine import RemoteVLLMEngine as LLM
    else:
        from vllm import LLM

    torch.manual_seed(args.seed)
    output = Path(args.out)
    output.mkdir(parents=True, exist_ok=True)
    original_source = Path(args.init_adapter).resolve() if args.init_adapter else None
    if original_source is not None:
        adapter_dir = original_source
    else:
        adapter_dir = (output / ".sft_initial_adapter").resolve()
        if not (adapter_dir / "adapter_model.safetensors").is_file():
            create_initial_peft_adapter(
                adapter_dir, args.model, args.lora_r, args.seed
            )
    validate_adapter(adapter_dir)

    tokenizer = AutoTokenizer.from_pretrained(args.model, local_files_only=True)
    if tokenizer.pad_token is None:
        tokenizer.pad_token = tokenizer.eos_token

    engine = LLM(
        model=args.model,
        dtype=args.dtype,
        tensor_parallel_size=1,
        enable_lora=True,
        max_loras=1,
        max_cpu_loras=1,
        max_lora_rank=args.lora_r,
        max_model_len=args.max_model_len,
        max_num_seqs=args.max_num_seqs,
        gpu_memory_utilization=args.gpu_memory_utilization,
        enable_prefix_caching=False,
        enforce_eager=args.enforce_eager,
        disable_log_stats=True,
        worker_extension_cls="vllm_es_worker.VLLMESWorkerExtension",
    )
    request = LoRARequest("sft_policy", 1, str(adapter_dir))
    engine.generate(
        ["Warm up."],
        [SamplingParams(temperature=0.0, max_tokens=1, seed=args.seed)],
        lora_request=[request],
        use_tqdm=False,
    )
    rpc_one(
        engine,
        "es_initialize",
        [request.lora_int_id],
        str(adapter_dir),
        adapter_scale(adapter_dir),
    )

    args.method = "sft"
    args.kl_lambda = 0.0
    args.init_adapter = str(adapter_dir)
    device = torch.device("cuda")
    dtype = torch.bfloat16 if args.dtype == "bfloat16" else torch.float16
    _, student, _, _ = core.build_models(args, dtype, device)
    student.train()
    trainable = [parameter for parameter in student.parameters() if parameter.requires_grad]
    optimizer = torch.optim.AdamW(trainable, lr=args.lr)
    if original_source is not None:
        optimizer_path = original_source / "optimizer.pt"
        if optimizer_path.is_file():
            optimizer.load_state_dict(
                torch.load(str(optimizer_path), map_location=device)
            )

    instruct = "Instruct" in args.model
    permute = args.permute_choices and args.dataset in ("mmlu", "medqa")
    train_prompts, _ = C.load_task(
        args.dataset,
        tokenizer,
        instruct,
        args.eval_size,
        args.train_size,
        data_seed,
        permute,
    )
    expected_visits = len(train_prompts) * args.epochs
    target_visits = args.max_visits or expected_visits
    if not 0 <= args.start_visit < target_visits <= expected_visits:
        raise SystemExit("visit range is outside train-size * epochs")

    sync_root = Path(
        tempfile.mkdtemp(
            prefix=f"sft_{os.environ.get('SLURM_JOB_ID', 'local')}_",
            dir=adapter_sync_parent(),
        )
    )
    atexit.register(shutil.rmtree, sync_root, ignore_errors=True)
    sync_dir = sync_root / "policy"

    def save_checkpoint(path):
        destination = Path(path)
        destination.mkdir(parents=True, exist_ok=True)
        student.save_pretrained(destination)
        torch.save(optimizer.state_dict(), destination / "optimizer.pt")

    def synchronize_policy():
        if sync_dir.exists():
            for candidate in sync_dir.glob("adapter_model.*"):
                candidate.unlink()
        student.save_pretrained(sync_dir)
        validate_adapter(sync_dir)
        rpc_one(
            engine,
            "es_initialize",
            [request.lora_int_id],
            str(sync_dir),
            adapter_scale(sync_dir),
        )

    print(
        f"[sft] vLLM={version}; model={args.model}; population={args.population}; "
        f"max_new={args.max_new}; visits={target_visits}",
        flush=True,
    )
    visits = args.start_visit
    used = skipped = 0
    started = time.monotonic()

    while visits < target_visits:
        item = train_prompts[visits % len(train_prompts)]
        synchronize_policy()
        prompts, permutations = _rollout_prompts(
            item, args.population, visits, permute, tokenizer, instruct
        )
        sampling = [
            SamplingParams(
                temperature=args.temp,
                top_p=0.95,
                max_tokens=args.max_new,
                seed=args.seed * 1_000_003 + visits * args.population + index,
            )
            for index in range(args.population)
        ]
        generated = engine.generate(
            prompts,
            sampling,
            lora_request=[request] * args.population,
            use_tqdm=False,
        )
        rollouts, prompt_lens, answers = [], [], []
        for result, permutation in zip(generated, permutations):
            sequence, prompt_len = request_to_sequence(
                result, tokenizer.eos_token_id
            )
            sequence = sequence.to(device=device, non_blocking=True)
            answer = C.extract_answer(result.outputs[0].text)
            if permutation is not None:
                answer = C.canonical_letter(answer, permutation)
            rollouts.append(sequence)
            prompt_lens.append(prompt_len)
            answers.append(answer)

        _, mode, agreement, valid = C.group_advantage(answers)
        loss = None
        if valid and agreement <= args.p_high:
            loss = core.mode_sft_update(
                student, optimizer, rollouts, prompt_lens, answers, mode
            )
            used += 1
        else:
            skipped += 1
        visits += 1

        elapsed = max(time.monotonic() - started, 1e-6)
        rate = (visits - args.start_visit) / elapsed * 3600
        loss_text = "-" if loss is None else f"{loss:.4f}"
        print(
            f"  [update] visit={visits} loss={loss_text} used={used} "
            f"skipped={skipped} rate={rate:.1f} visits/h",
            flush=True,
        )
        if args.snap_every and visits % args.snap_every == 0:
            save_checkpoint(output / f"snap{visits:06d}")

    save_checkpoint(output)
    print(f"[sft] complete: {output}", flush=True)


if __name__ == "__main__":
    main()

